def recopier_liens(apps, schema_editor):
    """Conserve les liens YouTube / TikTok déjà saisis (projet et galerie vidéo)."""
    from core.video import analyser
    Projet = apps.get_model('projets', 'Projet')
    VideoProjet = apps.get_model('projets', 'VideoProjet')
    for projet in Projet.objects.all():
        if analyser(projet.video_url):
            projet.lien_video = projet.video_url
            projet.save(update_fields=['lien_video'])
    # vidéos de galerie : seules celles avec un lien reconnu sont conservées
    for video in VideoProjet.objects.all():
        if not analyser(video.url):
            video.delete()


